namespace NameObjFactory {
    template < typename T >
    NameObj* createNameObj(const char* pName) {
        return reinterpret_cast< NameObj* >(new T(pName));
    }

    template < typename T >
    NameObj* createCenterOriginCube(const char* pName) {
        return reinterpret_cast< NameObj* >(new T(1, pName));
    }

    template < typename T >
    NameObj* createBaseOriginCube(const char* pName) {
        return reinterpret_cast< NameObj* >(new T(0, pName));
    }

    template < typename T >
    NameObj* createSphere(const char* pName) {
        return reinterpret_cast< NameObj* >(new T(2, pName));
    }

    template < typename T >
    NameObj* createBaseOriginCylinder(const char* pName) {
        return reinterpret_cast< NameObj* >(new T(3, pName));
    }
};  // namespace NameObjFactory

